    'usa-star-rating': UsaStarRatingElement;
    'usa-milestones': UsaMilestonesElement;
    'usa-masonry-flow': UsaMasonryFlowElement;
    'usa-compare': UsaCompareElement;
    'usa-cube-gallery': UsaCubeGalleryElement;
    'usa-dock': UsaDockElement;
